CREATE TYPE public.app_role AS ENUM ('admin','supervisor','user');
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL DEFAULT 'user',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'supervisor'); $$;
REVOKE ALL ON FUNCTION public.is_staff() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_staff() TO authenticated,service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_staff());
CREATE POLICY roles_admin ON public.user_roles FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,full_name text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',organization text NOT NULL DEFAULT '',job_title text NOT NULL DEFAULT '',mobile text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(full_name,organization,job_title,mobile) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_private_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_staff());
CREATE POLICY profiles_self_edit ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.validate_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(NEW.full_name))<2 OR length(trim(NEW.organization))<2 OR length(trim(NEW.job_title))<2 OR NEW.mobile !~ '^\+?[0-9 ()-]{7,20}$' THEN RAISE EXCEPTION 'الاسم والجهة والمسمى الوظيفي ورقم الجوال إلزامية'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER profiles_validate BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_profile();
CREATE FUNCTION public.create_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.raw_app_meta_data->>'provider'='email' AND (length(trim(coalesce(NEW.raw_user_meta_data->>'full_name','')))<2 OR length(trim(coalesce(NEW.raw_user_meta_data->>'organization','')))<2 OR length(trim(coalesce(NEW.raw_user_meta_data->>'job_title','')))<2 OR coalesce(NEW.raw_user_meta_data->>'mobile','') !~ '^\+?[0-9 ()-]{7,20}$') THEN RAISE EXCEPTION 'بيانات الحساب الإلزامية غير مكتملة'; END IF;
INSERT INTO public.profiles(id,email,full_name,organization,job_title,mobile) VALUES(NEW.id,coalesce(NEW.email,''),coalesce(NEW.raw_user_meta_data->>'full_name',''),coalesce(NEW.raw_user_meta_data->>'organization',''),coalesce(NEW.raw_user_meta_data->>'job_title',''),coalesce(NEW.raw_user_meta_data->>'mobile',''));
INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_account() FROM PUBLIC;
CREATE TRIGGER wathiq_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account();
CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_public ON public.categories FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY categories_staff ON public.categories FOR ALL TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE TABLE public.groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.groups TO authenticated; GRANT ALL ON public.groups TO service_role;
ALTER TABLE public.groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY groups_staff ON public.groups FOR ALL TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE TABLE public.group_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),group_id uuid NOT NULL REFERENCES public.groups(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.group_memberships TO authenticated; GRANT ALL ON public.group_memberships TO service_role;
ALTER TABLE public.group_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY memberships_read ON public.group_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_staff());
CREATE POLICY memberships_staff ON public.group_memberships FOR ALL TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE POLICY groups_member_read ON public.groups FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.group_memberships WHERE group_id=groups.id AND user_id=auth.uid()));
CREATE TABLE public.brand_settings (id integer PRIMARY KEY DEFAULT 1,title_font text NOT NULL DEFAULT 'Cairo',body_font text NOT NULL DEFAULT 'Cairo',refaq_logo text NOT NULL DEFAULT '/__l5e/assets-v1/9bac872d-db6d-4538-a64a-a7fc79cfcef3/refaq-logo-green.png',wathiq_logo text NOT NULL DEFAULT '/__l5e/assets-v1/c6abf752-0d72-4f55-9437-03d8c731d47f/wathiq-logo-02.png',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.brand_settings TO anon; GRANT SELECT,UPDATE ON public.brand_settings TO authenticated; GRANT ALL ON public.brand_settings TO service_role;
ALTER TABLE public.brand_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY brand_public ON public.brand_settings FOR SELECT TO anon,authenticated USING(id=1);
CREATE POLICY brand_staff ON public.brand_settings FOR UPDATE TO authenticated USING(id=1 AND public.is_staff()) WITH CHECK(id=1 AND public.is_staff());
CREATE FUNCTION public.validate_brand() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.title_font NOT IN ('Cairo','Tajawal','Almarai','IBM Plex Sans Arabic','Noto Sans Arabic','Noto Kufi Arabic','Readex Pro','Amiri') OR NEW.body_font NOT IN ('Cairo','Tajawal','Almarai','IBM Plex Sans Arabic','Noto Sans Arabic','Noto Kufi Arabic','Readex Pro','Amiri') THEN RAISE EXCEPTION 'خط غير مدعوم'; END IF; IF NOT (NEW.refaq_logo LIKE '/__l5e/assets-v1/%' OR NEW.refaq_logo LIKE 'https://vfndtiiztccebdfkaxaq.supabase.co/storage/v1/object/public/brand-assets/%') OR NOT (NEW.wathiq_logo LIKE '/__l5e/assets-v1/%' OR NEW.wathiq_logo LIKE 'https://vfndtiiztccebdfkaxaq.supabase.co/storage/v1/object/public/brand-assets/%') THEN RAISE EXCEPTION 'مصدر الشعار غير معتمد'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER brand_validate BEFORE UPDATE ON public.brand_settings FOR EACH ROW EXECUTE FUNCTION public.validate_brand();
INSERT INTO public.brand_settings(id) VALUES(1);
CREATE TRIGGER roles_updated BEFORE UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER categories_updated BEFORE UPDATE ON public.categories FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER groups_updated BEFORE UPDATE ON public.groups FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER memberships_updated BEFORE UPDATE ON public.group_memberships FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER brand_updated BEFORE UPDATE ON public.brand_settings FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE INDEX memberships_user_idx ON public.group_memberships(user_id);
